import {itemPositions} from './creator-schema.js';
import {keyboardRows} from './core.js';
import {DEFAULT_SHORTCUTS,chordCode} from './chord-core.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const round=n=>Number(n.toFixed(2));
const rect=(x,y,w,h,fill='#fffef9',stroke='#cbd8c6',r=3)=>`<rect x="${round(x)}" y="${round(y)}" width="${round(Math.max(1,w))}" height="${round(Math.max(1,h))}" rx="${r}" fill="${fill}" stroke="${stroke}"/>`;
const text=(x,y,label,size=9,fill='#214e3b',anchor='middle')=>`<text x="${round(x)}" y="${round(y)}" font-size="${size}" fill="${fill}" text-anchor="${anchor}" dominant-baseline="middle">${esc(label)}</text>`;
const path=(points,color='#1aa891',width=3,dash='')=>`<polyline points="${points.map(p=>round(p.x)+','+round(p.y)).join(' ')}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round" stroke-linejoin="round" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;
const tile=(x,y,w,h,label,active=false,size=9)=>rect(x,y,w,h,active?'#d9edbf':'#fffef9',active?'#6f9c62':'#cbd8c6')+text(x+w/2,y+h/2,label,size);
const labels=(value,max=11)=>Array.from(String(value)).slice(0,max).join('')+(Array.from(String(value)).length>max?'…':'');
function classic(){const rows=keyboardRows();let out=rect(16,9,288,22)+text(26,20,'Message',8,'#64745e','start');rows.forEach((row,r)=>{const h=14,y=38+r*17,w=(288-(row.length-1)*4)/row.length;if(r===1)out+=rect(12,y-2,296,h+4,'#e4f0d3','#82a86c');row.forEach((k,c)=>out+=tile(16+c*(w+4),y,w,h,k.label,r===1&&c===2,k.label.length>1?7:9));});return out;}
function chord(){let out=text(16,15,'BANK + SLOT',8,'#5e7559','start')+text(304,15,'Close fists → code',8,'#5e7559','end');DEFAULT_SHORTCUTS.forEach((s,i)=>{const x=16+i%5*58,y=28+Math.floor(i/5)*36;out+=rect(x,y,54,31,i===6?'#dfedcc':'#fffef9')+text(x+5,y+8,chordCode(i),7,'#6a8060','start')+text(x+27,y+21,labels(s.title,9),6.5);});return out;}
function sketch(block){let out=rect(24,15,272,144,'#fcfdf9','#c2d4b7',7)+path([{x:44,y:132},{x:276,y:132}],'#dce5d6',1,'3 4');const example=block.sketches?.[0]?.examples?.[0];if(example?.length){for(const stroke of example)out+=path(stroke.map(p=>({x:70+p.x*180,y:28+p.y*110})));}else out+=path([{x:107,y:131},{x:154,y:40},{x:202,y:131}])+path([{x:126,y:94},{x:182,y:94}]);out+=tile(111,166,30,19,block.sketches?.[0]?.label?.slice(0,3)||'A',true,11)+tile(146,166,30,19,'H',false,10)+tile(181,166,30,19,'R',false,10);return out;}
function board(block,kind){const positions=itemPositions(block);let out='';const circle=kind==='trace'||block.layout==='ring'||(block.scene?.selection.mode==='target'&&block.scene.bindings.some(b=>b.target==='rotation'));const area=circle?{x:76,y:10,w:168,h:168}:kind==='index'?{x:38,y:24,w:262,h:150}:{x:18,y:15,w:284,h:154};
 const locate=p=>({x:area.x+p.x*area.w,y:area.y+p.y*area.h});
 if(kind==='index'){for(let n=0;n<6;n++){out+=text(area.x+(n+.5)*area.w/6,12,n,8)+text(22,area.y+(n+.5)*area.h/6,n,8);}out+=rect(area.x,area.y+area.h/6,area.w,area.h/6,'#e6f1d9','none',0);out+=rect(area.x+2*area.w/6,area.y,area.w/6,area.h,'#e2eee5','none',0);}
 if(circle)out+=`<circle cx="160" cy="94" r="64" fill="none" stroke="#cbdcc1" stroke-dasharray="2 4"/>`;
 for(const p of positions){const q=locate(p),w=Math.max(9,p.w*area.w-(kind==='index'?3:1)),h=Math.max(9,p.h*area.h-(kind==='index'?3:1)),label=labels(p.item.label,circle?2:w<30?4:Math.max(4,Math.floor(w/5)));out+=p.item.kind==='label'?text(q.x,q.y,label,8):tile(q.x-w/2,q.y-h/2,w,h,label,kind==='index'&&p.i===8,circle?7:label.length>2?6.5:9);}
 if(kind==='swipe'||kind==='trace'){const point=c=>positions.find(p=>p.item.value?.toLowerCase()===c);const word='hello',points=[];for(let i=0;i<word.length;i++){const p=point(word[i]);if(!p)continue;if(kind==='trace'&&points.length)points.push({x:160,y:94});points.push(locate(p));}if(points.length){out+=path(points,'#15a990',circle?2:3);for(const p of [points[0],points.at(-1)])out+=`<circle cx="${round(p.x)}" cy="${round(p.y)}" r="3" fill="#174d40"/>`;}}
 if(block.scene?.selection.mode==='target'){const p=locate(block.scene.selection);out+=`<circle cx="${round(p.x)}" cy="${round(p.y)}" r="8" fill="none" stroke="#b48b32" stroke-width="2"/>`;}
 if(kind==='index')out+=text(18,184,'Row 1 · Col 2',7,'#587049','start')+rect(177,181,120,4,'#e0e7da','none',2)+rect(177,181,73,4,'#779c60','none',2);
 else if(kind==='swipe')out+=text(160,181,'hello',10);
 return out;}
export function thumbnailKind(env){const b=env.pages?.[0]?.blocks?.[0];if(!b)return 'empty';if(env.id==='relay-builtin-classic-v1')return 'classic';if(env.id==='relay-builtin-chord-v1')return 'chord';if(b.layout==='sketch')return 'sketch';if(['swipe','trace'].includes(b.input.behavior))return b.input.behavior;if(b.scene?.selection.mode==='index'||b.input.source==='finger-pair')return 'index';return 'layout';}
export function environmentThumbnail(env){const kind=thumbnailKind(env),b=env.pages?.[0]?.blocks?.[0],content=kind==='classic'?classic():kind==='chord'?chord():kind==='sketch'?sketch(b):b?board(b,kind):text(160,95,'Blank canvas',12);return `<div class="environment-thumbnail thumbnail-${kind}" data-thumbnail-kind="${kind}"><svg viewBox="0 0 320 194" role="img" aria-label="${esc(env.name)} layout preview" xmlns="http://www.w3.org/2000/svg"><rect width="320" height="194" fill="#edf3e7"/>${content}</svg></div>`;}
